ALTER TABLE systems
ADD COLUMN IF NOT EXISTS has_primary_dmi BOOLEAN NOT NULL DEFAULT FALSE;

UPDATE systems
SET has_primary_dmi = TRUE,
    archives_dirty = TRUE
WHERE code = 'XBOX';

ALTER TABLE discs
ADD COLUMN IF NOT EXISTS dmi_no_primary BOOLEAN NOT NULL DEFAULT FALSE;

UPDATE discs
SET dmi_no_primary = TRUE
WHERE id IN (48905, 49747, 51936, 54518);

CREATE TABLE IF NOT EXISTS system_media_dmi (
    system_code VARCHAR(16) NOT NULL REFERENCES systems(code) ON UPDATE CASCADE ON DELETE CASCADE,
    media_type_code VARCHAR(8) NOT NULL REFERENCES media_types(code) ON UPDATE CASCADE ON DELETE CASCADE,
    dmi_length INT NOT NULL CHECK (dmi_length > 4),
    trailer BYTEA NOT NULL,
    PRIMARY KEY (system_code, media_type_code)
);

INSERT INTO system_media_dmi (system_code, media_type_code, dmi_length, trailer) VALUES
    ('XBOX', 'xgd', 36, decode(repeat('00', 2016), 'hex')),
    ('XBOX360', 'xgd', 84, decode(repeat('00', 1504), 'hex')),
    ('WII', 'dvd5wii', 84, decode('', 'hex')),
    ('WII', 'dvd9wii', 84, decode('', 'hex'))
ON CONFLICT DO NOTHING;

UPDATE discs
SET dmi = substring(dmi FROM 1 FOR 36)
WHERE system_code = 'XBOX'
  AND media_type_code = 'xgd'
  AND octet_length(dmi) > 36;
